#!/usr/bin/env python3
"""Repair 41 review flags and close five bounded source gaps, preserving 78 accepted hashes."""
import json,copy,hashlib,os,math
from pathlib import Path
R=Path(__file__).resolve().parents[1];B='W04-L20';A='L20-author-20261019'
def read(p):return json.loads((R/p).read_text())
def write(p,x):(R/p).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def sha(q):return hashlib.sha256(json.dumps({k:v for k,v in q.items() if k not in ('status','reviewIds')},sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False).encode()).hexdigest()
if (R/f'audits/{B}-v2-review-manifest.json').exists():raise SystemExit('L20 v2 frozen: do not regenerate over reviewed objects.')
archive=f'data/question-batches/archive/{B}-v1.json'
if not (R/archive).exists():write(archive,read(f'data/question-batches/{B}.json'))
old=read(archive);b=copy.deepcopy(old);qm={q['id']:q for q in b['questions']};review=read(f'data/reviews/{B}-v1-independent.json');flag={r['questionId']:r for r in review if r['decision']=='flagged'};accepted=[q for q in old['questions'] if q['id'] not in flag]
assert len(flag)==41 and len(accepted)==78
for q in old['questions']:
 rv=next(r for r in review if r['questionId']==q['id']);assert rv['questionSha256']==sha(q)
for qid,rv in flag.items():
 q=qm[qid];assert q['version']==1;q.update(version=2,status='draft',reviewIds=[]);q['revisionAuthors']=sorted(set(q.get('revisionAuthors',[])+[A]))
 if 'conflictResolution' in q:q['conflictResolution']['questionVersion']=2
 if any(x.startswith('difficulty:') for x in rv['findings']):q['difficulty']='easy'
changedids=set()
def edit(short,opts,why,stem=None,**kw):
 q=qm[B+'-'+short];assert q['id'] in flag
 if stem is not None:q['stem']=stem
 assert len(opts)==len(why)==4
 for o in q['options']:o['text']=opts[int(o['id'][1:])-1]
 q['solution'].update(justification=why[0],simpleExplanation=why[0],optionExplanations={f'o{i+1}':('Correct. ' if f'o{i+1}' in q['correctOptionIds'] else 'Incorrect. ')+x for i,x in enumerate(why)},misconceptions=why[1:])
 for k,v in kw.items():
  if k in ('steps','formulas'):q['solution'][k]=v
  else:q[k]=v
 changedids.add(q['id']);return q

def persist():
 for c in b['concepts']:
  originals={q['stem']:qm[q['id']]['stem'] for q in old['questions'] if q['id'] in flag}
  c['examinationAngles']=[originals.get(t,t) for t in c.get('examinationAngles',[])]
 for q in accepted:assert q==qm[q['id']]
 assert b['sourceIssues']==old['sourceIssues'] and len(b['sourceIssues'])==13
 write(f'data/question-batches/{B}.json',b)
 (R/f'audits/handoffs/{B}-v2-progress.md').write_text(f'# L20 v2 repair checkpoint\nAll41 flagged objects versioned; {len(changedids)} targeted content repairs applied, plus difficulty-only changes. {len(b["questions"])} total questions;78 accepted objects/hashes and13 source issue records unchanged. Continue scripts/repair_W04_L20_v2.py from saved source, which regenerates only this owned batch from archivedv1 until freeze. No self-approval/canonical/Git writes.\n')
 print('L20 repair checkpoint',len(changedids),'content repairs;',len(b['questions']),'questions')
